package com.careerpilot.backend.modules.discovery.services;
import com.careerpilot.connector.sdk.*; import com.careerpilot.backend.modules.discovery.domain.ConnectorRegistration; import org.springframework.stereotype.Service; import java.util.*; import java.util.concurrent.*;
@Service public class ConnectorRegistry { private final Map<String,Connector> connectors=new ConcurrentHashMap<>(); public ConnectorRegistry(List<Connector> discovered){discovered.forEach(this::register);} public ConnectorRegistration register(Connector c){Objects.requireNonNull(c); if(c.getConnectorId()==null||c.getConnectorId().isBlank())throw new IllegalArgumentException("Connector id is required"); Connector old=connectors.putIfAbsent(c.getConnectorId(),c); if(old!=null&&!old.getVersion().equals(c.getVersion()))throw new IllegalArgumentException("Connector version conflict"); return describe(c);} public Connector get(String id){return Optional.ofNullable(connectors.get(id)).orElseThrow(()->new NoSuchElementException("Connector not found: "+id));} public List<ConnectorRegistration> list(){return connectors.values().stream().map(this::describe).sorted(Comparator.comparing(ConnectorRegistration::getId)).toList();} public List<Connector> enabled(){return connectors.values().stream().filter(Connector::isEnabled).toList();} public ConnectorRegistration enable(String id,boolean enabled){Connector c=get(id);c.setEnabled(enabled);return describe(c);} public List<ConnectorHealth> health(){return connectors.values().stream().map(c->c.isEnabled()?c.healthCheck():ConnectorHealth.builder().connectorId(c.getConnectorId()).status(ConnectorHealthStatus.DISABLED).build()).toList();} private ConnectorRegistration describe(Connector c){return ConnectorRegistration.builder().id(c.getConnectorId()).type(c.getConnectorType()).name(c.getDisplayName()).version(c.getVersion()).enabled(c.isEnabled()).build();} }
